/*
 * luci-app-traffic-stats - packet capture
 *
 * The daemon reads a copy of the traffic that crosses the router with an
 * AF_PACKET socket. This is a strictly read only operation: no firewall
 * rule, no route, no interface setting and no DNS configuration is ever
 * touched, so installing the application cannot affect connectivity.
 *
 * Capturing on the LAN bridge yields the per device view (the source MAC
 * of an outgoing frame and the destination MAC of an incoming frame). The
 * WAN side yields the complete view of the traffic leaving the router,
 * including the traffic generated by the router itself.
 */

#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_ether.h>
#include <linux/if_packet.h>
#include <net/if.h>
#include <poll.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#include "ts.h"

#define ETH_P_PPPOE 0x8864
#define ETH_P_PPPOE_IPV4 0x0021
#define ETH_P_PPPOE_IPV6 0x0057

struct cap_socket {
	int  fd;
	int  role;
	char name[32];
};

static struct cap_socket socks[MAX_IFACES * 2];
static int sock_count;
static volatile int capture_stop;
static volatile int capture_running;

static int open_socket(const char *name, int role)
{
	struct sockaddr_ll sll;
	struct ifreq ifr;
	int fd, rcvbuf;

	fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
	if (fd < 0) {
		ts_log("cannot open packet socket for %s: %s", name, strerror(errno));
		return -1;
	}

	memset(&ifr, 0, sizeof(ifr));
	snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), "%s", name);
	if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
		ts_log("interface %s not found", name);
		close(fd);
		return -1;
	}

	memset(&sll, 0, sizeof(sll));
	sll.sll_family = AF_PACKET;
	sll.sll_protocol = htons(ETH_P_ALL);
	sll.sll_ifindex = ifr.ifr_ifindex;

	if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
		ts_log("cannot bind to %s: %s", name, strerror(errno));
		close(fd);
		return -1;
	}

	rcvbuf = 4 * 1024 * 1024;
	setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf));

	memset(&socks[sock_count], 0, sizeof(socks[sock_count]));
	socks[sock_count].fd = fd;
	socks[sock_count].role = role;
	snprintf(socks[sock_count].name, sizeof(socks[sock_count].name), "%s", name);
	sock_count++;

	return 0;
}

int capture_open(struct state *st)
{
	int i;

	for (i = 0; i < st->cfg.lan_count; i++)
		open_socket(st->cfg.lan_ifaces[i], ROLE_LAN);

	for (i = 0; i < st->cfg.wan_count; i++)
		open_socket(st->cfg.wan_ifaces[i], ROLE_WAN);

	if (sock_count == 0)
		ts_log("warning: no interface could be captured");

	return sock_count;
}

void capture_close(struct state *st)
{
	int i;

	(void)st;

	/* let the capture thread leave its polling loop */
	capture_stop = 1;

	for (i = 0; i < 100; i++) {
		if (!capture_running)
			break;
		usleep(10000);
	}

	for (i = 0; i < sock_count; i++)
		if (socks[i].fd >= 0)
			close(socks[i].fd);

	sock_count = 0;
}

static int have_wan_socket(void)
{
	int i;

	for (i = 0; i < sock_count; i++)
		if (socks[i].role == ROLE_WAN)
			return 1;

	return 0;
}

static void account_packet(struct state *st, int role, const uint8_t *eth_src,
			   const uint8_t *eth_dst, int src_local, int dst_local,
			   uint32_t src4, uint32_t dst4, uint64_t bytes,
			   int is_dns, const uint8_t *l4, size_t l4len,
			   int is_tcp, int from_client)
{
	struct device *dev = NULL;
	struct destination *d = NULL;
	int count_dst = 0;

	if (st->cfg.verbose && st->pkts_debug[role] < 10) {
		st->pkts_debug[role]++;

		ts_log("pkt role=%d src=%08x dst=%08x local=%d/%d len=%llu", role,
		       (unsigned int)src4, (unsigned int)dst4, src_local, dst_local,
		       (unsigned long long)bytes);
	}

	if (src_local && !dst_local) {
		/* upload: the device sends data to an external peer */
		st->pkts_up++;
		if (role == ROLE_LAN && eth_src != NULL) {
			dev = device_get(st, eth_src, src4);
			if (dev != NULL) {
				dev->up += bytes;
				dev->last = ts_now();
			}
		}
		if (role == ROLE_WAN)
			st->wan_up += bytes;
		else
			st->lan_up += bytes;
		count_dst = 1;
	} else if (!src_local && dst_local) {
		/* download: an external peer sends data to a device */
		st->pkts_down++;
		if (role == ROLE_LAN && eth_dst != NULL) {
			dev = device_get(st, eth_dst, dst4);
			if (dev != NULL) {
				dev->down += bytes;
				dev->last = ts_now();
			}
		}
		if (role == ROLE_WAN)
			st->wan_down += bytes;
		else
			st->lan_down += bytes;
		count_dst = 1;
	} else if (src_local && dst_local && st->cfg.count_internal) {
		st->pkts_int++;
		if (role == ROLE_LAN && eth_src != NULL) {
			dev = device_get(st, eth_src, src4);
			if (dev != NULL) {
				dev->up_int += bytes;
				dev->last = ts_now();
			}
		}
	} else {
		st->pkts_unknown++;
	}

	/*
	 * The destination table is fed by the WAN side only, it already
	 * contains every byte that leaves the router. When no WAN interface
	 * can be captured the LAN side is used instead.
	 */
	if (count_dst && dst4 != 0 && (role == ROLE_WAN || !have_wan_socket())) {
		uint32_t peer = (src_local && !dst_local) ? dst4 : src4;

		d = dest_get(st, peer);
		if (d != NULL) {
			if (src_local && !dst_local) {
				d->up += bytes;
				d->up_pkts++;
			} else {
				d->down += bytes;
				d->down_pkts++;
			}
			d->last = ts_now();
		}
	}

	if (is_dns && l4 != NULL && l4len > 0)
		dns_parse_packet(st, l4, l4len, is_tcp, from_client);
}

static void handle_frame(struct state *st, struct cap_socket *cs, unsigned char *buf, ssize_t len)
{
	struct ethhdr *eh;
	uint16_t proto;
	size_t off = 14;
	unsigned int ipproto = 0;
	const uint8_t *ip;

	if (len < 14)
		return;

	eh = (struct ethhdr *)buf;
	proto = ntohs(eh->h_proto);

	if (proto == ETH_P_8021Q || proto == ETH_P_8021AD) {
		if (len < 18)
			return;
		proto = ntohs(*(uint16_t *)(buf + 16));
		off = 18;
	}

	if (proto == ETH_P_PPPOE) {
		/* PPPoE session: ver/type, code, session id, length, protocol */
		uint16_t pproto;

		if (len < (ssize_t)(off + 8))
			return;

		pproto = ntohs(*(uint16_t *)(buf + off + 6));
		off += 8;

		if (pproto == ETH_P_PPPOE_IPV4)
			proto = ETH_P_IP;
		else if (pproto == ETH_P_PPPOE_IPV6)
			proto = ETH_P_IPV6;
		else
			return;
	}

	if (proto == ETH_P_IPV6) {
		const uint8_t *ip6;
		unsigned int payload, next;
		int src_local, dst_local;
		int is_dns = 0, from_client = 0;
		const uint8_t *l4 = NULL;
		size_t l4len = 0;

		if (len < (ssize_t)(off + 40))
			return;

		ip6 = buf + off;
		payload = ntohs(*(uint16_t *)(ip6 + 4));
		next = ip6[6];

		src_local = is_local6(st, ip6 + 8);
		dst_local = is_local6(st, ip6 + 24);

		if (next == IPPROTO_UDP || next == IPPROTO_TCP) {
			size_t l4off = off + 40;

			if (len >= (ssize_t)(l4off + 4)) {
				uint16_t sport = ntohs(*(uint16_t *)(buf + l4off));
				uint16_t dport = ntohs(*(uint16_t *)(buf + l4off + 2));

				if (sport == 53 || dport == 53) {
					size_t hdr = (next == IPPROTO_UDP) ? 8 : 20;

					if (len >= (ssize_t)(l4off + hdr)) {
						l4 = buf + l4off + hdr;
						l4len = (size_t)(len - (ssize_t)(l4off + hdr));
						is_dns = 1;
						from_client = (dport == 53);
					}
				}
			}
		}

		account_packet(st, cs->role, eh->h_source, eh->h_dest,
			       src_local, dst_local, 0, 0, payload,
			       is_dns, l4, l4len, next == IPPROTO_TCP, from_client);

		return;
	}

	if (proto != ETH_P_IP)
		return;

	if (len < (ssize_t)(off + 20))
		return;

	ip = buf + off;

	if ((ip[0] >> 4) != 4)
		return;

	{
		unsigned int ihl = (ip[0] & 0x0f) * 4;
		unsigned int tot = ntohs(*(uint16_t *)(ip + 2));
		uint32_t src, dst;
		uint64_t payload;
		int is_dns = 0, from_client = 0;
		const uint8_t *l4 = NULL;
		size_t l4len = 0;
		if (ihl < 20 || tot < ihl)
			return;

		src = ip[12] | (ip[13] << 8) | (ip[14] << 16) | ((uint32_t)ip[15] << 24);
		dst = ip[16] | (ip[17] << 8) | (ip[18] << 16) | ((uint32_t)ip[19] << 24);
		ipproto = ip[9];

		payload = tot - ihl;

		if (ipproto == IPPROTO_UDP || ipproto == IPPROTO_TCP) {
			size_t l4off = off + ihl;

			if (len >= (ssize_t)(l4off + 4)) {
				uint16_t sport = ntohs(*(uint16_t *)(buf + l4off));
				uint16_t dport = ntohs(*(uint16_t *)(buf + l4off + 2));

				if (sport == 53 || dport == 53) {
					size_t hdr = (ipproto == IPPROTO_UDP) ? 8 : 20;

					if (len >= (ssize_t)(l4off + hdr)) {
						l4 = buf + l4off + hdr;
						l4len = (size_t)(len - (ssize_t)(l4off + hdr));
						is_dns = 1;
						from_client = (dport == 53);
					}
				}
			}
		}

		account_packet(st, cs->role, eh->h_source, eh->h_dest,
			       is_local4(st, src), is_local4(st, dst), src, dst,
			       payload, is_dns, l4, l4len,
			       ipproto == IPPROTO_TCP, from_client);
	}
}

/*
 * The packets are collected first and accounted with a single lock. If the
 * lock was taken for every single packet, a busy network would starve the
 * main thread that writes the snapshots.
 */
#define PKT_BATCH_MAX 64
#define PKT_BATCH_BUF 9216

struct pkt_batch_entry {
	uint8_t buf[PKT_BATCH_BUF];
	int captured;   /* the number of bytes received */
	int stored;     /* the number of bytes kept for the analysis */
	int sock;       /* the index of the interface the packet came from */
};

/* account the collected packets, one lock for the whole batch */
static void account_batch(struct state *st, struct pkt_batch_entry *batch, int nbatch)
{
	int i;

	pthread_mutex_lock(&st->lock);

	for (i = 0; i < nbatch; i++) {
		st->packets++;
		st->bytes += (uint64_t)batch[i].captured;
		handle_frame(st, &socks[batch[i].sock], batch[i].buf, batch[i].stored);
	}

	pthread_mutex_unlock(&st->lock);
}

static void *capture_thread(void *arg)
{
	struct state *st = arg;
	struct pollfd pfd[MAX_IFACES * 2];
	struct pkt_batch_entry *batch;
	unsigned char buf[65536];
	int i;

	batch = calloc(PKT_BATCH_MAX, sizeof(*batch));
	if (batch == NULL) {
		ts_log("cannot allocate the packet batch");
		return NULL;
	}

	capture_running = 1;

	while (!capture_stop) {
		int n = 0, rc, nbatch = 0;
		unsigned long errors = 0;

		for (i = 0; i < sock_count; i++) {
			pfd[n].fd = socks[i].fd;
			pfd[n].events = POLLIN;
			pfd[n].revents = 0;
			n++;
		}

		if (n == 0)
			break;

		rc = poll(pfd, n, 200);
		if (rc < 0) {
			if (errno == EINTR)
				continue;
			break;
		}

		/*
		 * Collect the pending packets, this needs no lock. The socket
		 * has to be drained completely, a burst of packets would
		 * overflow the receive buffer and the statistics would lose
		 * them.
		 */
		for (i = 0; i < n; i++) {
			if (!(pfd[i].revents & POLLIN))
				continue;

			for (;;) {
				ssize_t len = recv(socks[i].fd, buf, sizeof(buf), MSG_DONTWAIT);

				if (len <= 0) {
					if (len < 0 && errno == EINTR)
						continue;
					if (len < 0 && errno != EAGAIN && errno != EWOULDBLOCK)
						errors++;
					break;
				}

				batch[nbatch].captured = (int)len;
				batch[nbatch].stored = (len > PKT_BATCH_BUF) ? PKT_BATCH_BUF : (int)len;
				batch[nbatch].sock = i;
				memcpy(batch[nbatch].buf, buf, batch[nbatch].stored);
				nbatch++;

				/*
				 * Account the collected packets with a single
				 * lock, otherwise the main thread is starved
				 * by a busy network.
				 */
				if (nbatch >= PKT_BATCH_MAX) {
					account_batch(st, batch, nbatch);
					nbatch = 0;
				}
			}
		}

		if (nbatch > 0)
			account_batch(st, batch, nbatch);

		if (errors > 0) {
			pthread_mutex_lock(&st->lock);
			st->errors += errors;
			pthread_mutex_unlock(&st->lock);
		}
	}

	free(batch);

	capture_running = 0;

	return NULL;
}

static pthread_t capture_tid;

void capture_run(struct state *st)
{
	if (sock_count == 0)
		return;

	if (pthread_create(&capture_tid, NULL, capture_thread, st) != 0)
		ts_log("cannot start capture thread: %s", strerror(errno));
	else
		pthread_detach(capture_tid);
}
